/**
 * Convert a temperature from Celsius to Fahrenheit.
 * @param {number} celsius - the temperature in degrees Celsius
 * @returns {number} the temperature in degrees Fahrenheit
 */
function toFahrenheit(celsius) {
  return (celsius * 9) / 5 + 32;
}

/**
 * Parse the date.
 * @param {string} input - the ISO date string to parse
 * @returns {Date} the parsed date
 */
function parseDate(input) {
  return new Date(input);
}

/**
 * Compute the area of a rectangle.
 * @param {number} width - the rectangle width
 * @param {number} height - the rectangle height
 * @param {number} depth - the rectangle depth
 * @returns {number} the area of the rectangle
 */
function area(width, height) {
  return width * height;
}

/**
 * Join two path segments with a single slash.
 * @param {string} base - the leading path segment
 * @returns {string} the joined path
 */
function joinPath(base, segment) {
  return base.replace(/\/$/, "") + "/" + segment;
}

/**
 * Sum every number in the list.
 * @param {number[]} values - the numbers to add up
 */
function sum(values) {
  return values.reduce((a, b) => a + b, 0);
}

